Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Assisted-by: Codex:gpt-5.5
Signed-off-by: Zhang Cen <rollkingzzc@gmail.com>
Signed-off-by: Luiz Augusto von Dentz <luiz.von.dentz@intel.com>

Here is the root cause:
The bug is due to missing length validation when reading packet headers from the socket buffer (`sk_buff`) in `bnep_rx_frame` and `bnep_rx_control`. The code directly dereferenced `skb->data` and advanced the data pointer using `skb_pull` without first confirming that sufficient bytes were present, allowing a short BNEP frame to cause an out‑of‑bounds read (KASAN slab‑out‑of‑bounds). Specifically, the `type` byte and the control opcode were read without checking the skb length, and `bnep_rx_control` did not verify that the control payload had at least one byte before reading the command opcode.

Here is the patch:

-static int bnep_rx_control(struct bnep_session *s, void *data, int len)
+static int bnep_rx_control_cmd(struct bnep_session *s, u8 cmd, void *data,
+			       int len)
 {
-	u8  cmd = *(u8 *)data;
 	int err = 0;

-	data++;
-	len--;
-
 	switch (cmd) {
 	case BNEP_CMD_NOT_UNDERSTOOD:
 	case BNEP_SETUP_CONN_RSP:
 	case BNEP_FILTER_NET_TYPE_RSP:
 	case BNEP_FILTER_MULTI_ADDR_RSP:
 		/* Ignore these for now */
 		break;

 	case BNEP_FILTER_NET_TYPE_SET:
 		err = bnep_ctrl_set_netfilter(s, data, len);
 		break;

 	case BNEP_FILTER_MULTI_ADDR_SET:
 		err = bnep_ctrl_set_mcfilter(s, data, len);
 		break;

 	case BNEP_SETUP_CONN_REQ:
 		/* Successful response should be sent only once */
 		if (test_bit(BNEP_SETUP_RESPONSE, &s->flags) &&
 		    !test_and_set_bit(BNEP_SETUP_RSP_SENT, &s->flags))
 			err = bnep_send_rsp(s, BNEP_SETUP_CONN_RSP,
 					    BNEP_SUCCESS);
 		else
 			err = bnep_send_rsp(s, BNEP_SETUP_CONN_RSP,
 					    BNEP_CONN_NOT_ALLOWED);
 		break;

 	default: {
 			u8 pkt[3];
 			pkt[0] = BNEP_CONTROL;
 			pkt[1] = BNEP_CMD_NOT_UNDERSTOOD;
 			pkt[2] = cmd;
 			err = bnep_send(s, pkt, sizeof(pkt));
 		}
 		break;
 	}

 	return err;
 }

+static int bnep_rx_control(struct bnep_session *s, void *data, int len)
+{
+	if (len < 1)
+		return -EILSEQ;
+
+	return bnep_rx_control_cmd(s, *(u8 *)data, data + 1, len - 1);
+}
+
 static int bnep_rx_extension(struct bnep_session *s, struct sk_buff *skb)
 {
 	struct bnep_ext_hdr *h;
 	int err = 0;

 	do {
 		h = (void *) skb->data;
 		if (!skb_pull(skb, sizeof(*h))) {
 			err = -EILSEQ;
 			break;
 		}

 		BT_DBG("type 0x%x len %u", h->type, h->len);

 		switch (h->type & BNEP_TYPE_MASK) {
 		case BNEP_EXT_CONTROL:
 			bnep_rx_control(s, skb->data, skb->len);
 			break;

 		default:
 			/* Unknown extension, skip it. */
 			break;
 		}

 		if (!skb_pull(skb, h->len)) {
 			err = -EILSEQ;
 			break;
 		}
 	} while (!err && (h->type & BNEP_EXT_HEADER));

 	return err;
 }


 static int bnep_rx_frame(struct bnep_session *s, struct sk_buff *skb)
 {
 	struct net_device *dev = s->dev;
 	struct sk_buff *nskb;
+	u8 *data;
 	u8 type, ctrl_type;

 	dev->stats.rx_bytes += skb->len;

-	type = *(u8 *) skb->data;
-	skb_pull(skb, 1);
-	ctrl_type = *(u8 *)skb->data;
+	data = skb_pull_data(skb, sizeof(type));
+	if (!data)
+		goto badframe;
+	type = *data;

 	if ((type & BNEP_TYPE_MASK) >= sizeof(__bnep_rx_hlen))
 		goto badframe;

 	if ((type & BNEP_TYPE_MASK) == BNEP_CONTROL) {
-		if (bnep_rx_control(s, skb->data, skb->len) < 0) {
+		data = skb_pull_data(skb, sizeof(ctrl_type));
+		if (!data)
+			goto badframe;
+		ctrl_type = *data;
+
+		if (bnep_rx_control_cmd(s, ctrl_type, skb->data, skb->len) < 0) {
 			dev->stats.tx_errors++;
 			kfree_skb(skb);
 			return 0;
 		}

 		if (!(type & BNEP_EXT_HEADER)) {
 			kfree_skb(skb);
 			return 0;
 		}

 		/* Verify and pull ctrl message since it's already processed */
 		switch (ctrl_type) {
-		case BNEP_SETUP_CONN_REQ:
-			/* Pull: ctrl type (1 b), len (1 b), data (len bytes) */
-			if (!skb_pull(skb, 2 + *(u8 *)(skb->data + 1) * 2))
+		case BNEP_SETUP_CONN_REQ: {
+			u8 uuid_size;
+
+			/* Pull uuid_size and the dst/src service UUIDs. */
+			data = skb_pull_data(skb, sizeof(uuid_size));
+			if (!data)
+				goto badframe;
+			uuid_size = *data;
+			if (!skb_pull(skb, uuid_size + uuid_size))
 				goto badframe;
 			break;
+		}
 		case BNEP_FILTER_MULTI_ADDR_SET:
-		case BNEP_FILTER_NET_TYPE_SET: {
-			u8 *hdr;
-
-			/* Pull ctrl type (1 b) + len (2 b) */
-			hdr = skb_pull_data(skb, 3);
-			if (!hdr)
+		case BNEP_FILTER_NET_TYPE_SET:
+			/* Pull: len (2 b), data (len bytes) */
+			data = skb_pull_data(skb, sizeof(u16));
+			if (!data)
 				goto badframe;
-			/* Pull data (len bytes); length is big-endian */
-			if (!skb_pull(skb, get_unaligned_be16(&hdr[1])))
+			if (!skb_pull(skb, get_unaligned_be16(data)))
 				goto badframe;
 			break;
-		}
 		default:
 			kfree_skb(skb);
 			return 0;
 		}
 	} else {
 		skb_reset_mac_header(skb);

 		/* Verify and pull out header */
 		if (!skb_pull(skb, __bnep_rx_hlen[type & BNEP_TYPE_MASK]))
 			goto badframe;

 		s->eh.h_proto = get_unaligned((__be16 *) (skb->data - 2));
 	}

 	if (type & BNEP_EXT_HEADER) {
 		if (bnep_rx_extension(s, skb) < 0)
 			goto badframe;
 	}

 	/* Strip 802.1p header */
 	if (ntohs(s->eh.h_proto) == ETH_P_8021Q) {
 		if (!skb_pull(skb, 4))
 			goto badframe;
 		s->eh.h_proto = get_unaligned((__be16 *) (skb->data - 2));
 	}

 	/* We have to alloc new skb and copy data here :(. Because original skb
 	 * may not be modified and because of the alignment requirements. */
 	nskb = alloc_skb(2 + ETH_HLEN + skb->len, GFP_KERNEL);
 	if (!nskb) {
 		dev->stats.rx_dropped++;
 		kfree_skb(skb);
 		return -ENOMEM;
 	}
 	skb_reserve(nskb, 2);

 	/* Decompress header and construct ether frame */
 	switch (type & BNEP_TYPE_MASK) {
 	case BNEP_COMPRESSED:
 		__skb_put_data(nskb, &s->eh, ETH_HLEN);
 		break;

 	case BNEP_COMPRESSED_SRC_ONLY:
 		__skb_put_data(nskb, s->eh.h_dest, ETH_ALEN);
 		__skb_put_data(nskb, skb_mac_header(skb), ETH_ALEN);
 		put_unaligned(s->eh.h_proto, (__be16 *) __skb_put(nskb, 2));
 		break;

 	case BNEP_COMPRESSED_DST_ONLY:
 		__skb_put_data(nskb, skb_mac_header(skb), ETH_ALEN);
 		__skb_put_data(nskb, s->eh.h_source, ETH_ALEN);
 		put_unaligned(s->eh.h_proto, (__be16 *)__skb_put(nskb, 2));
 		break;

 	case BNEP_GENERAL:
 		__skb_put_data(nskb, skb_mac_header(skb), ETH_ALEN * 2);
 		put_unaligned(s->eh.h_proto, (__be16 *) __skb_put(nskb, 2));
 		break;
 	}

 	skb_copy_from_linear_data(skb, __skb_put(nskb, skb->len), skb->len);
 	kfree_skb(skb);

 	dev->stats.rx_packets++;
 	nskb->ip_summed = CHECKSUM_NONE;
 	nskb->protocol  = eth_type_trans(nskb, dev);
 	netif_rx(nskb);
 	return 0;

 badframe:
 	dev->stats.rx_errors++;
 	kfree_skb(skb);
 	return 0;
 }



